600	//
601	// Large content is sharded across goroutines; output is byte-identical either
602	// way. See jsonlContent.
603	func JSONLContent(content string) (string, error) {
604		return jsonlContentImpl(content, String, concurrencySafeRedactor)
605	}
606	
607	// Whether a per-leaf redactor may be called from several goroutines at once.
608	//
609	// This is a property of the redactor, not of the entry point that supplies it,
610	// so it is passed explicitly rather than implied by which internal function a
611	// caller happens to reach: String is pure and shardable, while the OPF flow's
612	// collector closures accumulate into a shared map and slice and are not.
613	const (
614		concurrencySafeRedactor   = true
615		concurrencyUnsafeRedactor = false
616	)
617	
618	// jsonlContentImpl is the body of JSONLContent parameterized by a per-leaf
619	// redactor. JSONLContent passes String (regex layers only). The OPF-enabled
620	// flow uses two passes: one with a collector that records leaves and returns
621	// identity, one with a redactor that combines regex layers with cached OPF
622	// spans for the recorded leaves.
623	//
624	// concurrencySafe reports whether redactor tolerates concurrent calls; when it
625	// does, large content is sharded across goroutines.
626	func jsonlContentImpl(content string, redactor func(string) string, concurrencySafe bool) (string, error) {
627		if result, handled, err := redactSingleJSONValue(content, redactor); handled {
628			return result, err
629		}
630		lines := strings.Split(content, "\n")
631		if !concurrencySafe {
632			return redactJSONLLines(lines, redactor)
633		}
634		return redactJSONLLinesSharded(lines, redactor)
635	}
636	
637	// redactSingleJSONValue handles the case where the whole content is one JSON
638	// value (e.g. pretty-printed single objects like OpenCode export) so
639	// field-aware redaction is used instead of falling back to entropy-based
640	// detection on raw text lines, which would corrupt high-entropy identifiers.
641	//
642	// handled is false when the content is JSONL, so the caller processes it line by
643	// line. Neither the shard split nor the incremental prefix cache in
644	// checkpoint/redact_cache.go applies to the single-value shape.
645	func redactSingleJSONValue(content string, redactor func(string) string) (result string, handled bool, err error) {
646		trimmed := strings.TrimSpace(content)
647		if len(trimmed) == 0 {
648			return "", false, nil
649		}
650		parsed, ok := parseSingleJSONValue(trimmed)
651		if !ok {
652			return "", false, nil
653		}
654		result, err = applyJSONReplacements(content, collectJSONLReplacements(parsed, redactor))
655		if err != nil {
656			return "", true, err
657		}
658		return result, true, nil
659	}
660	
661	// IsLineDelimited reports whether JSONLContent will redact content line by line
662	// rather than as a single JSON value.
663	//
664	// Callers that split content and redact the pieces separately MUST check this
665	// first. The line path composes -- redact(A+B) == redact(A)+redact(B) for
666	// newline-terminated A -- because each line is redacted in isolation. The
667	// single-JSON-value path does NOT: it is field-aware across the whole document,
668	// so redacting a fragment of it instead falls back to raw regex and entropy
669	// detection over partial JSON, which is the identifier corruption
670	// redactSingleJSONValue exists to avoid.
671	//
672	// A filename is not a safe proxy for this. OpenCode writes a single JSON object
673	// to the same full.jsonl path that other agents write JSONL to.
674	func IsLineDelimited(content []byte) bool {
675		trimmed := bytes.TrimSpace(content)
676		if len(trimmed) == 0 {
677			return false
678		}
679		// Decode stops at the first complete value, so this does not scan a large
680		// JSONL body. Content that is not JSON at all still goes down the line path,
681		// where each line is redacted independently.
682		dec := json.NewDecoder(bytes.NewReader(trimmed))
683		var parsed any
684		if err := dec.Decode(&parsed); err != nil {
685			return true
686		}
687		return !isSingleJSONValue(dec)
688	}
689	
690	// parseSingleJSONValue reports whether s decodes as exactly one JSON value.
691	//
692	// Uses a streaming decoder so a large JSONL input is not copied: Decode stops at
693	// the first complete value, then isSingleJSONValue checks for a second one. A
694	// decode failure is a routing signal, not an error — it just means the content
695	// is not a single JSON value.
696	func parseSingleJSONValue(s string) (any, bool) {
697		dec := json.NewDecoder(strings.NewReader(s))
698		var parsed any
699		if err := dec.Decode(&parsed); err != nil {
700			return nil, false
701		}
702		return parsed, isSingleJSONValue(dec)
703	}
704	
705	// jsonlShardTargetBytes is the rough content size per shard, and hence also the
706	// sharding threshold: content under 2x this yields fewer than two shards and
707	// runs sequentially.
708	//
709	// The win is not purely parallelism: redaction cost per byte climbs with input
710	// size (allocation and GC pressure over one large buffer), so cutting the
711	// content into small pieces is cheaper per byte *and* lets pieces run
712	// concurrently. Measured on a 20MB Codex transcript: 43s sequential vs 2.1s
713	// across 12 shards. Hence a byte-sized shard target rather than one shard per
714	// core, with worker count bounding actual concurrency.
715	const jsonlShardTargetBytes = 1 << 20 // 1MiB
716	
717	// redactJSONLLinesSharded splits lines into contiguous byte-balanced groups,
718	// redacts them concurrently, and rejoins them in order. Output is byte-identical
719	// to redactJSONLLines over the same lines, because each line is redacted in
720	// isolation and shard boundaries fall between lines.
721	//
722	// redactor MUST be safe for concurrent use.
723	func redactJSONLLinesSharded(lines []string, redactor func(string) string) (string, error) {
724		// Balance shards by bytes, not by line count: agent transcripts mix
725		// thousands of short lines with occasional multi-MB tool results, so equal
726		// line counts would leave one oversized shard as the tail.
727		bounds := shardLineBounds(lines, jsonlShardTargetBytes)
728		if len(bounds) < 2 {
729			return redactJSONLLines(lines, redactor)
730		}
731	
732		results := make([]string, len(bounds))
733		g := new(errgroup.Group)
734		g.SetLimit(runtime.GOMAXPROCS(0))
735		for i, b := range bounds {
736			g.Go(func() error {
737				out, err := redactJSONLLines(lines[b.lo:b.hi], redactor)
738				if err != nil {
739					return err
740				}
741				results[i] = out
742				return nil
743			})
744		}
745		if err := g.Wait(); err != nil {
746			return "", fmt.Errorf("redacting JSONL shard: %w", err)
747		}
748	
749		// Shards are contiguous line ranges, so rejoining them with "\n" in order
750		// reproduces the sequential join exactly.
751		return strings.Join(results, "\n"), nil
752	}
753	
754	// lineRange is a half-open range of line indexes forming one shard.
755	type lineRange struct{ lo, hi int }
756	
757	// shardLineBounds groups lines into contiguous ranges of roughly targetBytes
758	// each. A single line larger than targetBytes becomes its own shard rather than
759	// being split, since lines are the indivisible unit of redaction.
760	func shardLineBounds(lines []string, targetBytes int) []lineRange {
761		var bounds []lineRange
762		lo, running := 0, 0
763		for i, line := range lines {
764			running += len(line) + 1 // +1 for the rejoined newline
765			if running >= targetBytes && i+1 < len(lines) {
766				bounds = append(bounds, lineRange{lo: lo, hi: i + 1})
767				lo, running = i+1, 0
768			}
769		}
770		if lo < len(lines) {
771			bounds = append(bounds, lineRange{lo: lo, hi: len(lines)})
772		}
773		return bounds
774	}
775	
776	// redactJSONLLines redacts each line independently and rejoins them with "\n".
777	//
778	// Every line is handled in isolation: no state carries between lines, which is
779	// what makes sharding across goroutines (jsonlContentConcurrent) produce
780	// byte-identical output to a sequential pass. Keep it that way — a redactor or
781	// line rule that depended on earlier lines would silently break that guarantee.
782	func redactJSONLLines(lines []string, redactor func(string) string) (string, error) {
783		var b strings.Builder
784		// Redaction only ever shrinks or preserves length, so the input size is a
785		// sound capacity estimate and avoids repeated doubling of a large buffer.
786		size := len(lines) - 1
787		for _, line := range lines {
788			size += len(line)
789		}
790		if size > 0 {
791			b.Grow(size)
792		}
793		for i, line := range lines {
794			if i > 0 {
795				b.WriteByte('\n')
796			}
797			lineTrimmed := strings.TrimSpace(line)
798			if lineTrimmed == "" {
799				b.WriteString(line)
800				continue
801			}
802			var parsed any
803			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
804				b.WriteString(redactor(line))
805				continue
806			}
807			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed, redactor))
808			if err != nil {
809				return "", err
810			}
811			b.WriteString(result)
812		}
813		return b.String(), nil
814	}
815	
816	// StringWithPrivacyFilter augments String with the OpenAI Privacy Filter.
817	// Use only at condensation/export boundaries; per-turn writes must use
818	// String to avoid the OPF shell-out cost inside the agent loop.
819	func StringWithPrivacyFilter(ctx context.Context, s string) string {
820		regions := detectAllLayers(s)
821		regions = append(regions, detectOPF(ctx, getOPFConfig(), s)...)
822		return applyRegions(s, regions)
823	}
824	
825	// JSONLContentWithPrivacyFilter augments JSONLContent with the OpenAI
826	// Privacy Filter via batched inference. Walks the content twice: pass 1
827	// collects unique prose-shaped leaves into a single RedactBatch call;
828	// pass 2 applies the eight regex layers per leaf plus the cached OPF spans
829	// for that leaf. One OPF shell-out covers the whole transcript instead of
830	// one per leaf — without batching, a typical 500-leaf transcript would
831	// take many minutes per commit.
832	//
833	// Falls back to the plain JSONLContent flow when OPF is unconfigured, the
834	// breaker is tripped, no categories are enabled, or the batch call errors.
835	func JSONLContentWithPrivacyFilter(ctx context.Context, content string) (string, error) {
836		cfg := getOPFConfig()
837		if cfg == nil || !cfg.Enabled || cfg.runtime == nil || opfBreakerTripped.Load() {
838			return jsonlContentImpl(content, String, concurrencySafeRedactor)
839		}
840		cats := enabledCategories(cfg)
841		if len(cats) == 0 {
842			return jsonlContentImpl(content, String, concurrencySafeRedactor)
843		}
844	
845		// Pass 1: collect eligible (has-space, deduped) leaves. The collector
846		// closure returns identity so the JSONL walker doesn't mutate content.
847		seen := make(map[string]struct{})
848		var inputs []string
849		if _, err := jsonlContentImpl(content, func(v string) string {
850			if strings.ContainsRune(v, ' ') {
851				if _, ok := seen[v]; !ok {
852					seen[v] = struct{}{}
853					inputs = append(inputs, v)
854				}
855			}
856			return v
857		}, concurrencyUnsafeRedactor); err != nil {
858			return "", err
859		}
860	
861		// Pass 2: single batched OPF call.
862		spansByInput := make(map[string][]Span, len(inputs))
863		if len(inputs) > 0 {
864			fmt.Fprintln(opfStderr, "→ OpenAI Privacy Filter: scanning transcript…")
865			start := time.Now()
866			batched, err := cfg.runtime.RedactBatch(ctx, inputs, cats)
867			if err != nil {
868				handleOPFFailure(ctx, cfg, err)
869				return jsonlContentImpl(content, String, concurrencySafeRedactor)
870			}
871			fmt.Fprintf(opfStderr, "✓ OpenAI Privacy Filter: done (%.1fs)\n", time.Since(start).Seconds())
872			// A short return means the runtime gave us fewer span slices than
873			// inputs — the tail leaves would receive zero OPF spans and the
874			// caller would proceed as if OPF had found nothing. That silently
875			// produces under-redacted output and is indistinguishable from a
876			// "no PII present" result. Treat as a runtime contract violation:
877			// trip the breaker so the pre-push rewrite's post-loop
878			// OPFBreakerTripped() check aborts before the Entire-OPF-Applied
879			// trailer can be attached to under-redacted commits. The production
880			// shell-out always returns len(inputs), so this only fires for a
881			// misbehaving custom runtime — but the cost of leaving it dormant
882			// is too high for a privacy contract.
883			if len(batched) != len(inputs) {
884				shortErr := fmt.Errorf("opf runtime returned %d span slices for %d inputs", len(batched), len(inputs))
885				handleOPFFailure(ctx, cfg, shortErr)
886				return jsonlContentImpl(content, String, concurrencySafeRedactor)
887			}
888			for i, in := range inputs {
889				spansByInput[in] = batched[i]
890			}
891		}
892	
893		// Pass 3: per-leaf regex layers + cached OPF spans.
894		return jsonlContentImpl(content, func(v string) string {
895			regions := detectAllLayers(v)
896			regions = append(regions, opfSpanRegions(v, spansByInput[v], cfg)...)
897			return applyRegions(v, regions)
898		}, concurrencySafeRedactor)
899	}
900	
901	// applyJSONReplacements applies collected (original, redacted) string pairs
902	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
903	// Returns s unchanged if repls is empty.
904	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
905		if len(repls) == 0 {
906			return s, nil
907		}
908		for _, r := range repls {
909			origJSON, err := jsonEncodeString(r.original)
910			if err != nil {
911				return "", err
912			}
913			replJSON, err := jsonEncodeString(r.redacted)
914			if err != nil {
915				return "", err
916			}
917			if r.key == "" {
918				s = strings.ReplaceAll(s, origJSON, replJSON)
919				continue
920			}
921			keyJSON, err := jsonEncodeString(r.key)
922			if err != nil {
923				return "", err
924			}
925			s = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
926		}
927		return s, nil
928	}
929	
930	// replaceKeyedJSONValue replaces every occurrence of origJSON that follows
931	// keyJSON + optional whitespace + ':' + optional whitespace. Restricts
932	// substitution to value positions so a key's own redacted text is not
933	// rewritten when it collides with another field's value.
934	func replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON string) string {
935		if !strings.Contains(s, keyJSON) {
936			return s
937		}
938		var b strings.Builder
939		b.Grow(len(s))
940		i := 0
941		for i < len(s) {
942			j := strings.Index(s[i:], keyJSON)
943			if j < 0 {
944				b.WriteString(s[i:])
945				break
946			}
947			keyEnd := i + j + len(keyJSON)
948			b.WriteString(s[i : i+j])
949			b.WriteString(keyJSON)
950			p := keyEnd
951			for p < len(s) && isJSONWhitespace(s[p]) {
952				p++
953			}
954			if p >= len(s) || s[p] != ':' {
955				i = keyEnd
956				continue
957			}
958			p++
959			for p < len(s) && isJSONWhitespace(s[p]) {
960				p++
961			}
962			if p+len(origJSON) <= len(s) && s[p:p+len(origJSON)] == origJSON {
963				b.WriteString(s[keyEnd:p])
964				b.WriteString(replJSON)
965				i = p + len(origJSON)
966				continue
967			}
968			i = keyEnd
969		}
970		return b.String()
971	}
972	
973	func isJSONWhitespace(c byte) bool {
974		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
975	}
976	
977	// isSingleJSONValue returns true if the decoder has reached EOF (no more
978	// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
979	// object) from JSONL (multiple concatenated values). We attempt a second Decode
980	// and require io.EOF rather than relying on dec.More(), which is documented for
981	// use inside arrays/objects and not for top-level value boundaries.
982	func isSingleJSONValue(dec *json.Decoder) bool {
983		var discard json.RawMessage
984		return dec.Decode(&discard) == io.EOF
985	}
986	
987	// collectJSONLReplacements walks a parsed JSON value and collects unique
988	// string replacements via the supplied per-leaf redactor. JSONLContent
989	// passes String; the OPF-enabled flow passes a closure that combines the
990	// regex layers with cached batched OPF spans.
991	func collectJSONLReplacements(v any, redactor func(string) string) []jsonReplacement {
992		seen := make(map[string]bool)
993		var repls []jsonReplacement
994		var walk func(key string, credentialContext bool, v any)
995		walk = func(key string, credentialContext bool, v any) {
996			switch val := v.(type) {
997			case map[string]any:
998				if shouldSkipJSONLObject(val) {
999					return
1000				}
1001				childCredentialContext := credentialContext || isCredentialJSONObject(val)
1002				for k, child := range val {
1003					if shouldSkipJSONLField(k) {
1004						continue
1005					}
1006					walk(k, childCredentialContext, child)
1007				}
1008			case []any:
1009				for _, child := range val {
1010					walk("", credentialContext, child)
1011				}
1012			case string:
1013				redacted := redactor(val)
1014				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
1015					redacted = RedactedPlaceholder
1016				}
1017				if redacted != val {
1018					seenKey := key + "\x00" + val
1019					if !seen[seenKey] {
1020						seen[seenKey] = true
1021						repls = append(repls, jsonReplacement{key: key, original: val, redacted: redacted})
1022					}
1023				}
1024			}
1025		}
1026		walk("", false, v)
1027		return repls
1028	}
1029	
1030	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
1031	// Skips signature fields (any key ending in "signature"), ID fields (ending in "id"/"ids"),
1032	// and common path/directory fields.
1033	func shouldSkipJSONLField(key string) bool {
1034		lower := strings.ToLower(key)
1035	
1036		// Skip signature fields: cryptographic attestations, not secrets. Covers
1037		// "signature" (Claude Code) and provider variants like "thinkingSignature"
1038		// (Oh My Pi). Their values are high-entropy base64, so the entropy scanner
1039		// would otherwise redact them — corrupting extended-thinking signatures and
1040		// breaking transcript replay ("Invalid `signature` in `thinking` block").
1041		if strings.HasSuffix(lower, "signature") {
1042			return true
1043		}
1044	
1045		// Skip ID fields
1046		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
1047			return true
1048		}
1049	
1050		// Skip common path and directory fields from agent transcripts.
