// mergeInvestigate replaces the investigate config from the override (whole-object
// replacement, parallel to how summary_generation is handled but simpler — the
// investigate schema is small and lacks per-field merge semantics).
func mergeInvestigate(settings *EntireSettings, raw map[string]json.RawMessage) error {
	investigateRaw, ok := raw["investigate"]
	if !ok {
		return nil
	}
	var cfg InvestigateConfig
	if err := unmarshalField("investigate", investigateRaw, &cfg); err != nil {
		return err
	}
	settings.Investigate = &cfg
	return nil
}

// mergeScalarFields merges simple bool, *bool, string, and int fields from raw JSON.
func mergeScalarFields(settings *EntireSettings, raw map[string]json.RawMessage) error {
	if err := mergeRawBool(raw, "enabled", &settings.Enabled); err != nil {
		return err
	}
	// "local_dev" is deliberately absent — a deprecated no-op, see
	// EntireSettings.LocalDev.
	if err := mergeRawBool(raw, "absolute_git_hook_path", &settings.AbsoluteGitHookPath); err != nil {
		return err
	}
	if err := mergeRawBool(raw, "external_agents", &settings.ExternalAgents); err != nil {
		return err
	}
	if err := mergeRawBoolPtr(raw, "async_mirror_requests", &settings.AsyncMirrorRequests); err != nil {
		return err
	}
	if err := mergeRawBool(raw, "vercel", &settings.Vercel); err != nil {
		return err
	}
	if err := mergeRawBoolPtr(raw, "telemetry", &settings.Telemetry); err != nil {
		return err
	}
	if err := mergeRawBoolPtr(raw, "sign_checkpoint_commits", &settings.SignCheckpointCommits); err != nil {
		return err
	}
	if err := mergeRawStringNonEmpty(raw, "log_level", &settings.LogLevel); err != nil {
		return err
	}
	if err := mergeRawStringNonEmpty(raw, "review_default_profile", &settings.ReviewDefaultProfile); err != nil {
		return err
	}
	if err := mergeRawStringNonEmpty(raw, "review_fix_agent", &settings.ReviewFixAgent); err != nil {
		return err
	}
	if err := mergeRawInt(raw, "summary_timeout_seconds", &settings.SummaryTimeoutSeconds); err != nil {
		return err
	}
	return nil
}

func mergeRawBool(raw map[string]json.RawMessage, key string, dst *bool) error {
	v, ok := raw[key]
	if !ok {
		return nil
	}
	return unmarshalField(key, v, dst)
}

func mergeRawBoolPtr(raw map[string]json.RawMessage, key string, dst **bool) error {
	v, ok := raw[key]
	if !ok {
		return nil
	}
	var b bool
	if err := unmarshalField(key, v, &b); err != nil {
		return err
	}
	*dst = &b
	return nil
}

func mergeRawStringNonEmpty(raw map[string]json.RawMessage, key string, dst *string) error {
	v, ok := raw[key]
	if !ok {
		return nil
	}
	var s string
	if err := unmarshalField(key, v, &s); err != nil {
		return err
	}
	if s != "" {
		*dst = s
	}
	return nil
}

func mergeRawInt(raw map[string]json.RawMessage, key string, dst *int) error {
	v, ok := raw[key]
	if !ok {
		return nil
	}
	return unmarshalField(key, v, dst)
}

func unmarshalField(key string, data json.RawMessage, dst any) error {
	if err := json.Unmarshal(data, dst); err != nil {
		return fmt.Errorf("parsing %s field: %w", key, err)
	}
	return nil
}

func mergeStrategyOptions(settings *EntireSettings, raw map[string]json.RawMessage) error {
	optionsRaw, ok := raw["strategy_options"]
	if !ok {
		return nil
	}
	var opts map[string]any
	if err := unmarshalField("strategy_options", optionsRaw, &opts); err != nil {
		return err
	}
	if settings.StrategyOptions == nil {
		settings.StrategyOptions = opts
	} else {
		for k, v := range opts {
			settings.StrategyOptions[k] = v
		}
	}
	return nil
}

func mergeSummaryGeneration(settings *EntireSettings, raw map[string]json.RawMessage) error {
	summaryRaw, ok := raw["summary_generation"]
	if !ok {
		return nil
	}
	if settings.SummaryGeneration == nil {
		settings.SummaryGeneration = &SummaryGenerationSettings{}
	}

	var summaryFields map[string]json.RawMessage
	if err := unmarshalField("summary_generation", summaryRaw, &summaryFields); err != nil {
		return err
	}

	_, modelInOverride := summaryFields["model"]

	if providerRaw, ok := summaryFields["provider"]; ok {
		var provider string
		if err := unmarshalField("summary_generation.provider", providerRaw, &provider); err != nil {
			return err
		}
		// If the override switches providers without also setting a model,
		// the base's model was tuned to the old provider and would likely
		// cause a runtime failure when handed to the new one (e.g. codex
		// rejecting "sonnet"). Clear it so the new provider falls back to
		// its own default.
		if provider != settings.SummaryGeneration.Provider && !modelInOverride {
			settings.SummaryGeneration.Model = ""
		}
		settings.SummaryGeneration.Provider = provider
	}

	if modelRaw, ok := summaryFields["model"]; ok {
		var model string
		if err := unmarshalField("summary_generation.model", modelRaw, &model); err != nil {
			return err
		}
		settings.SummaryGeneration.Model = model
	}
	return nil
}

func mergeCommitLinking(settings *EntireSettings, raw map[string]json.RawMessage) error {
	commitLinkingRaw, ok := raw["commit_linking"]
	if !ok {
		return nil
	}
	var cl string
	if err := unmarshalField("commit_linking", commitLinkingRaw, &cl); err != nil {
		return err
	}
	if cl == "" {
		return nil
	}
	switch cl {
	case CommitLinkingAlways, CommitLinkingPrompt:
		settings.CommitLinking = cl
	default:
		return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
	}
	return nil
}

// mergeRedaction merges redaction overrides into existing RedactionSettings.
// Only fields present in the override JSON are applied.
func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("parsing redaction: %w", err)
	}
	if piiRaw, ok := raw["pii"]; ok {
		if dst.PII == nil {
			dst.PII = &PIISettings{}
		}
		if err := mergePIISettings(dst.PII, piiRaw); err != nil {
			return err
		}
	}
	if csRaw, ok := raw["custom_redactions"]; ok {
		if err := mergeStringMap(&dst.CustomRedactions, csRaw, "redaction.custom_redactions"); err != nil {
			return err
		}
	}
	if opfRaw, ok := raw["openai_privacy_filter"]; ok {
		if dst.OpenAIPrivacyFilter == nil {
			dst.OpenAIPrivacyFilter = &OPFSettings{}
		}
		if err := mergeOPFSettings(dst.OpenAIPrivacyFilter, opfRaw); err != nil {
			return err
		}
	}
	if extRaw, ok := raw["externalize_images"]; ok {
		var v bool
		if err := json.Unmarshal(extRaw, &v); err != nil {
			return fmt.Errorf("parsing redaction.externalize_images: %w", err)
		}
		dst.ExternalizeImages = v
	}

	// Scanner engine selection affects everyone who reads the repo's
	// checkpoints, so it is honored from the committed settings file only.
	for _, k := range []string{"betterleaks", "goredact"} {
		if _, ok := raw[k]; ok {
			slog.Warn("redaction scanner settings are ignored in settings.local.json; set them in .entire/settings.json",
				slog.String("key", "redaction."+k))
		}
	}

	return nil
}

// validateOPFSettings rejects unknown category names so typos surface at
// parse time. Silent zero-detection of a privacy category is effectively
// a correctness bug — the user thinks they're protected but they're not.
func validateOPFSettings(opf *OPFSettings) error {
	if opf == nil {
		return nil
	}
	for name := range opf.Categories {
		if !redact.IsKnownOPFCategory(name) {
			return fmt.Errorf("openai_privacy_filter.categories has unknown key %q (see docs/security-and-privacy.md for the supported set)", name)
		}
	}
	if opf.TimeoutSeconds < 0 {
		return fmt.Errorf("openai_privacy_filter.timeout_seconds must be greater than or equal to 0 (got %d)", opf.TimeoutSeconds)
	}
	switch opf.PromptDefault {
	case "", OPFPromptAsk, OPFPromptNever, OPFPromptAlways:
		// ok
	default:
		return fmt.Errorf("openai_privacy_filter.prompt_default must be one of %q, %q, %q (got %q)",
			OPFPromptAsk, OPFPromptNever, OPFPromptAlways, opf.PromptDefault)
	}
	return nil
}

// mergeOPFSettings merges OPF overrides into existing OPFSettings. Only
// fields present in the override JSON are applied; missing fields preserve
// the base value.
func mergeOPFSettings(dst *OPFSettings, data json.RawMessage) error {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("parsing openai_privacy_filter: %w", err)
	}
	if v, ok := raw["enabled"]; ok {
		if err := json.Unmarshal(v, &dst.Enabled); err != nil {
			return fmt.Errorf("parsing openai_privacy_filter.enabled: %w", err)
		}
	}
	if v, ok := raw["categories"]; ok {
		var cats map[string]bool
		if err := json.Unmarshal(v, &cats); err != nil {
			return fmt.Errorf("parsing openai_privacy_filter.categories: %w", err)
		}
		if dst.Categories == nil {
			dst.Categories = make(map[string]bool, len(cats))
		}
		for k, b := range cats {
			dst.Categories[k] = b
		}
	}
	if v, ok := raw["command"]; ok {
		if err := json.Unmarshal(v, &dst.Command); err != nil {
			return fmt.Errorf("parsing openai_privacy_filter.command: %w", err)
		}
	}
	if v, ok := raw["timeout_seconds"]; ok {
		if err := json.Unmarshal(v, &dst.TimeoutSeconds); err != nil {
			return fmt.Errorf("parsing openai_privacy_filter.timeout_seconds: %w", err)
		}
	}
	if v, ok := raw["prompt_default"]; ok {
		if err := json.Unmarshal(v, &dst.PromptDefault); err != nil {
			return fmt.Errorf("parsing openai_privacy_filter.prompt_default: %w", err)
		}
	}
	return validateOPFSettings(dst)
}

// mergePIISettings merges PII overrides into existing PIISettings.
// Only fields present in the override JSON are applied; missing fields
// are preserved from the base settings.
func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("parsing pii: %w", err)
	}
	if v, ok := raw["enabled"]; ok {
		if err := json.Unmarshal(v, &dst.Enabled); err != nil {
			return fmt.Errorf("parsing pii.enabled: %w", err)
		}
	}
	if v, ok := raw["email"]; ok {
		var b bool
		if err := json.Unmarshal(v, &b); err != nil {
			return fmt.Errorf("parsing pii.email: %w", err)
		}
		dst.Email = &b
	}
	if v, ok := raw["phone"]; ok {
		var b bool
		if err := json.Unmarshal(v, &b); err != nil {
			return fmt.Errorf("parsing pii.phone: %w", err)
		}
		dst.Phone = &b
	}
	if v, ok := raw["address"]; ok {
		var b bool
		if err := json.Unmarshal(v, &b); err != nil {
			return fmt.Errorf("parsing pii.address: %w", err)
		}
		dst.Address = &b
	}
	if v, ok := raw["custom_patterns"]; ok {
		if err := mergeStringMap(&dst.CustomPatterns, v, "pii.custom_patterns"); err != nil {
			return err
		}
	}
	return nil
}

// mergeStringMap unmarshals raw into a string map and merges it into dst,
// adopting the parsed map wholesale when dst is nil. field names the setting
// in parse errors.
func mergeStringMap(dst *map[string]string, raw json.RawMessage, field string) error {
	var m map[string]string
	if err := json.Unmarshal(raw, &m); err != nil {
		return fmt.Errorf("parsing %s: %w", field, err)
	}
	if *dst == nil {
		*dst = m
		return nil
	}
	for k, v := range m {
		(*dst)[k] = v
	}
	return nil
}

// IsSetUp returns true if Entire has been set up in the current repository.
// This checks if .entire/settings.json exists.
// Use this to avoid creating files/directories in repos where Entire was never enabled.
func IsSetUp(ctx context.Context) bool {
	return entireFileExists(ctx, SettingsName)
}

// FilesPresent reports whether each settings file exists, keeping an access
// failure distinct from absence. IsSetUp and IsSetUpLocal collapse both into
// false, which is right for a gate but wrong for `entire status`, whose whole
// job is to say why it cannot see something.
func FilesPresent(ctx context.Context) (project, local bool, err error) {
	root, err := entiredir.OpenForRead(ctx)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return false, false, nil
		}
		return false, false, fmt.Errorf("cannot access %s: %w", paths.EntireDir, err)
	}
	project, err = fileExists(root, SettingsName)
	if err != nil {
		return false, false, fmt.Errorf("cannot access project settings file: %w", err)
	}
	local, err = fileExists(root, SettingsLocalName)
	if err != nil {
		return false, false, fmt.Errorf("cannot access local settings file: %w", err)
	}
	return project, local, nil
}

func fileExists(root *os.Root, name string) (bool, error) {
	if _, err := root.Lstat(name); err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return false, nil
		}
		return false, err //nolint:wrapcheck // caller names the file
	}
	return true, nil
}

// IsSetUpLocal returns true if .entire/settings.local.json exists. Callers that
// pick a write target need the two scopes separately, which IsSetUpAny folds
// together.
func IsSetUpLocal(ctx context.Context) bool {
	return entireFileExists(ctx, SettingsLocalName)
}

// IsSetUpAny returns true if Entire has been set up in the current repository,
// checking both .entire/settings.json and .entire/settings.local.json.
// Use this to detect any prior setup, even if only local settings exist.
func IsSetUpAny(ctx context.Context) bool {
	return IsSetUp(ctx) || IsSetUpLocal(ctx)
}

// entireFileExists reports whether name exists directly under .entire. Lstat,
// not Stat: a settings file that is a dangling symlink still counts as "set up"
// here, exactly as it did before, and the root refuses to follow one out of
// .entire regardless.
func entireFileExists(ctx context.Context, name string) bool {
	root, err := entiredir.OpenForRead(ctx)
	if err != nil {
		return false
	}
	_, err = root.Lstat(name)
	return err == nil
}

// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
// "Set up" spans either scope — .entire/settings.json OR
// .entire/settings.local.json — so it must check IsSetUpAny, not IsSetUp.
// `entire enable --local` writes only settings.local.json and never creates the
// base file; gating on the base file alone would treat such a local-only repo
// as inactive and make every hook a silent no-op, dropping all checkpoint
// capture for that documented workflow. The IsSetUpAny guard is still required
// so a never-enabled repo (no settings file in any scope) is not treated as
// enabled by Load's default Enabled: true. Any settings read error is treated
// as disabled (fail closed).
// Use this for hooks that should be no-ops when Entire is not active.
func IsSetUpAndEnabled(ctx context.Context) bool {
	if !IsSetUpAny(ctx) {
		return false
	}
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.Enabled
}

// IsFilteredFetchesEnabled checks if filtered fetches should be used.
// When enabled, filtered fetches always resolve remote names to URLs first so
// git does not persist promisor settings onto named remotes in local config.
// Returns false by default.
func IsFilteredFetchesEnabled(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.IsFilteredFetchesEnabled()
}

// IsTelemetryEnabled reports whether the user opted in to anonymous usage
// analytics. Telemetry is opt-in: an absent key means no, so every tracker
// call site must gate on this rather than on Telemetry being non-nil. Does not
// consider ENTIRE_TELEMETRY_OPTOUT — the trackers honor that env opt-out
// themselves (telemetry.IsEnvOptedOut).
func (s *EntireSettings) IsTelemetryEnabled() bool {
	return s != nil && s.Telemetry != nil && *s.Telemetry
}

// IsTelemetryEnabled loads settings and reports the telemetry opt-in. Returns
// false when settings cannot be loaded — telemetry never fails open.
func IsTelemetryEnabled(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.IsTelemetryEnabled()
}

// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
// Returns false by default if settings cannot be loaded or the key is missing.
func IsSummarizeEnabled(ctx context.Context) bool {
	settings, err := Load(ctx)
	if err != nil {
		return false
	}
	return settings.IsSummarizeEnabled()
}

// IsImageExternalizationEnabled reports whether inline base64 images should be
// lifted out of transcripts into the checkpoint asset store. Opt-in via
// redaction.externalize_images, or the ENTIRE_EXTERNALIZE_IMAGES=1 env override
// (handy for testing/rollout). Off by default.
func IsImageExternalizationEnabled(ctx context.Context) bool {
	if v := os.Getenv("ENTIRE_EXTERNALIZE_IMAGES"); v == "1" || v == "true" {
		return true
	}
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.Redaction != nil && s.Redaction.ExternalizeImages
}

// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
func (s *EntireSettings) IsSummarizeEnabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
	if !ok {
		return false
	}
	enabled, ok := summarizeOpts["enabled"].(bool)
	if !ok {
		return false
	}
	return enabled
}

// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
type CheckpointRemoteConfig struct {
	Provider string // e.g., "github"
	Repo     string // e.g., "org/checkpoints-repo"
}

// Owner returns the owner portion of the repo field (before the slash).
// Returns empty string if the repo field doesn't contain a slash.
func (c *CheckpointRemoteConfig) Owner() string {
	parts := strings.SplitN(c.Repo, "/", 2)
	if len(parts) < 2 {
		return ""
	}
	return parts[0]
}

// HasCheckpointRemoteKey reports whether a checkpoint_remote entry exists in
// strategy options at all — deliberately including malformed entries that
// GetCheckpointRemote rejects (it returns nil for absent AND malformed, so it
// cannot distinguish "no intent" from "botched intent"). Presence in any form
// means the user intends a checkpoint remote.
func (s *EntireSettings) HasCheckpointRemoteKey() bool {
	if s.StrategyOptions == nil {
		return false
	}
	_, ok := s.StrategyOptions["checkpoint_remote"]
	return ok
}

// CheckpointRemoteIsLocalOnly reports whether a checkpoint_remote entry is
// present in .entire/settings.local.json.
//
// That file is gitignored and per-clone, so a checkpoint_remote living there
// is this developer's own explicit choice. Callers use this to distinguish
// "I configured where my checkpoints go" from "I inherited a committed setting
// that points at the upstream project's checkpoint repo".
//
// The filename alone does not establish that — see localLayerTrackedReason.
// This reads the file directly rather than through Load, so it repeats the
// tracked check the loader applies to the local layer —
// without it, the ownership signal this gates could be inherited from the very
// upstream it is meant to distinguish.
//
// Best-effort: an unreadable, malformed, or unverifiable local file reports
// false, which is the conservative answer (callers then fall back to weaker
// ownership signals).
func CheckpointRemoteIsLocalOnly(ctx context.Context) bool {
	path, raw, exists, err := LoadLocalRaw(ctx)
	if err != nil || !exists {
		return false
	}
	if classifyLocalSettings(ctx, path) != localOwn {
		return false
	}
	return rawHasKey(raw, "strategy_options", "checkpoint_remote")
}

// GetCheckpointRemote returns the configured checkpoint remote.
// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
// Returns nil if not configured, wrong type, or missing required fields.
func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
	if s.StrategyOptions == nil {
		return nil
	}
	val, ok := s.StrategyOptions["checkpoint_remote"]
	if !ok {
		return nil
	}
	m, ok := val.(map[string]any)
	if !ok {
		return nil
	}
	provider, providerOK := m["provider"].(string)
	repo, repoOK := m["repo"].(string)
	if !providerOK || !repoOK || provider == "" || repo == "" {
		return nil
	}
	if !strings.Contains(repo, "/") {
		return nil
	}
	return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
}

// GetCheckpointPushRemote returns the configured checkpoint push remote name.
// Stored in strategy_options.checkpoint_push_remote as a plain git remote
// name (e.g. "origin", "private"). This selects WHICH configured remote
// carries checkpoint data — distinct from checkpoint_remote, which derives a
// dedicated URL. Returns "" if unset, empty, or not a string.
func (s *EntireSettings) GetCheckpointPushRemote() string {
	if s.StrategyOptions == nil {
		return ""
	}
	val, ok := s.StrategyOptions["checkpoint_push_remote"].(string)
	if !ok {
		return ""
	}
	return val
}

// IsFilteredFetchesEnabled checks if fetches should use --filter=blob:none.
// When enabled, filtered fetches always use resolved URLs rather than remote
// names to avoid persisting promisor settings onto named remotes.
func (s *EntireSettings) IsFilteredFetchesEnabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	val, ok := s.StrategyOptions["filtered_fetches"].(bool)
	return ok && val
}

// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
// Returns true if push_sessions is explicitly set to false.
func (s *EntireSettings) IsPushSessionsDisabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	val, exists := s.StrategyOptions["push_sessions"]
	if !exists {
		return false
	}
	if boolVal, ok := val.(bool); ok {
		return !boolVal // disabled = !push_sessions
	}
	return false
}

// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
// Returns false by default if settings cannot be loaded or the key is missing.
func IsExternalAgentsEnabled(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.ExternalAgents
}

// IsAsyncMirrorRequestsEnabled reports whether mirror creation uses the async request route.
func (s *EntireSettings) IsAsyncMirrorRequestsEnabled() bool {
	return s.AsyncMirrorRequests == nil || *s.AsyncMirrorRequests
}

// IsSignCheckpointCommitsEnabled returns true if checkpoint commits should be signed.
// Defaults to true when the setting is not explicitly set.
func (s *EntireSettings) IsSignCheckpointCommitsEnabled() bool {
	return s.SignCheckpointCommits == nil || *s.SignCheckpointCommits
}

// IsSignCheckpointCommitsEnabled checks if checkpoint commit signing is enabled in settings.
// Returns true by default if settings cannot be loaded or the key is missing.
func IsSignCheckpointCommitsEnabled(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return true
	}
	return s.IsSignCheckpointCommitsEnabled()
}

// Save saves the settings to .entire/settings.json.
func Save(ctx context.Context, settings *EntireSettings) error {
	return saveToFile(ctx, settings, EntireSettingsFile)
}

// SaveLocal saves the settings to .entire/settings.local.json.
func SaveLocal(ctx context.Context, settings *EntireSettings) error {
	return saveToFile(ctx, settings, EntireSettingsLocalFile)
}

// saveToFile saves settings to the specified file path.
func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
	// Get absolute path for the file
	filePathAbs, err := entiredir.PathTo(ctx, filePath)
	if err != nil {
		return fmt.Errorf("resolving settings path: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling settings: %w", err)
	}

	if err := writeConfinedAtomic(filePathAbs, data, 0o644); err != nil {
		return fmt.Errorf("writing settings file: %w", err)
	}
	return nil
}

package settings

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"path/filepath"
	"strings"
	"sync"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
)

// localLayerTrackedReason explains why a tracked .entire/settings.local.json
// is ignored.
//
// The whole point of the local layer is that it is per-clone and per-developer:
// it is gitignored, it is where `entire enable --local` writes, and other code
// treats "present in the local file" as proof the developer chose it
// personally. A tracked local file breaks that premise — .gitignore does not
// apply to a path that is already tracked, so `git add -f
// .entire/settings.local.json` commits it and a fresh clone materializes it
// with whatever the committer put there. It then silently overrides project
// settings for everyone who clones, which is both a correctness surprise and,
// for settings naming a binary to execute, a way to run code on other people's
// machines through an ordinary pull request.
//
// Rejection ignores the layer rather than failing the load. Erroring would let
// one committed file brick every Entire command in the repo — including
// `status` and `doctor`, the tools needed to diagnose it.
const localLayerTrackedReason = "it is tracked in git, so it is not local to this clone — it arrives with the repository and overrides project settings for everyone"

// enforceOPFCommandTrust drops redaction.openai_privacy_filter.command unless
// it came from a local file positively verified as this developer's own.
//
// The command becomes argv[0] of an exec in the pre-push OPF rewrite (see
// redact.ConfigurePrivacyFilter -> newShellOut), so whoever controls the string
// controls what Entire runs on the developer's machine. .entire/settings.json
// is version-controlled, so honoring it from there would let an ordinary pull
// request carry a command pointing at a payload committed alongside it — and a
// JSON settings diff does not read as executable to a reviewer. The pre-push
// prompt is no defense: it never names the command, prompt_default "always"
// skips it, and non-TTY pushes auto-run.
//
// localData is the raw local-file bytes, nil when the file is absent or its
// layer was dropped as tracked. When the command does come from there, this
// re-verifies with the deep (index AND HEAD) check and requires localOwn:
// unlike the layer as a whole, an unverifiable repository fails CLOSED here,
// because the cost of being wrong is executing an attacker's binary rather
// than losing a preference.
//
// Rejection is a downgrade, never an error: Command resets to "" and
// ConfigurePrivacyFilter falls back to resolving "opf" on $PATH, which Go's
// exec.ErrDot protects against "." entries. If that binary is missing, the
// pre-push rewrite fails closed rather than pushing content the user believed
// OPF had scanned.
func enforceOPFCommandTrust(ctx context.Context, s *EntireSettings, localSettingsPath string, localData []byte) {
	if s == nil || s.Redaction == nil || s.Redaction.OpenAIPrivacyFilter == nil {
		return
	}
	opf := s.Redaction.OpenAIPrivacyFilter
	if opf.Command == "" {
		return
	}

	var reason string
	switch {
	case !localSetsOPFCommand(localData):
		reason = "it did not come from .entire/settings.local.json"
	case classifyLocalSettingsDeep(ctx, localSettingsPath) != localOwn:
		reason = "the local settings file could not be verified as untracked"
	default:
		return
	}

	// Record rather than log, for two reasons. A log line in
	// .entire/logs/entire.log is not a signal the user will see, and the
	// consumer can put this on stderr where it belongs. And the loader is
	// reached while the cli package resolves the log level, so keeping it
	// log-free keeps it off any future re-entrancy path into the logger
	// (Init no longer calls out under its lock, but the loader should not
	// depend on that).
	opf.rejectedCommand = opf.Command
	opf.rejectionReason = reason
	opf.Command = ""
}

// localSetsOPFCommand reports whether the local override file explicitly sets
// redaction.openai_privacy_filter.command.
//
// Presence of the key is what matters, not the merged value: the project file
// and the local file may set the same string, and comparing effective values
// after the merge would misattribute that to the project layer. A malformed
// local file yields false, which is the safe direction — the merge itself
// fails separately with a parse error.
func localSetsOPFCommand(data []byte) bool {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return false
	}
	return rawHasKey(raw, "redaction", "openai_privacy_filter", "command")
}

// rawHasKey reports whether a nested key is present in a decoded JSON object,
// walking objects along the way. A missing or non-object link yields false.
//
// Presence is the question, not value: two layers may set the same string, so
// comparing effective values after a merge would misattribute provenance.
//
// The first key is a separate parameter rather than part of the variadic so
// that "no key at all" cannot be expressed. A plain `path ...string` accepted
// an empty call that indexed out of range at run time — a latent panic in a
// predicate that gates a security boundary. This shape makes the compiler
// reject it instead of relying on every caller to pass enough arguments.
func rawHasKey(parent map[string]json.RawMessage, first string, rest ...string) bool {
	key := first
	for _, next := range rest {
		parent = rawObject(parent, key)
		key = next
	}
	_, ok := parent[key]
	return ok
}

// rawObject returns parent[key] decoded as a JSON object, or nil when the key
// is absent or does not hold an object. Indexing the nil result is safe, so
// lookups can be chained without intermediate checks.
func rawObject(parent map[string]json.RawMessage, key string) map[string]json.RawMessage {
	v, ok := parent[key]
	if !ok {
		return nil
	}
	var out map[string]json.RawMessage
	if err := json.Unmarshal(v, &out); err != nil {
		return nil
	}
	return out
}

// localTrust is the loader's verdict on .entire/settings.local.json.
//
// localUnverifiable is the zero value so a forgotten assignment fails in the
// safe direction. The two consumers use it with deliberately opposite
// policies: the layer as a whole is dropped only on localTracked (proof
// required, because losing every local setting over an unreadable repository
// is the worse failure), while the exec-bearing OPF command requires localOwn
// and treats localUnverifiable as hostile.
type localTrust int

const (
	localUnverifiable localTrust = iota // repository could not be read
	localTracked                        // proven present in the index (or HEAD, for a deep check)
	localOwn                            // verified not versioned, or no repository to clone from
)

// classifyLocalSettings checks the git index only.
//
// The index is what a delivered attack shows up in: a pull request that
// commits .entire/settings.local.json puts it in the index of every clone that
// checks the branch out. HEAD is deliberately NOT consulted here. The only
// state the index misses is "committed, then git rm --cached", and checkout
// does not produce a file that is absent from the index — so that state is one
// the local developer created, not one that arrived with the repository.
//
// Skipping HEAD is what keeps this affordable for the broad population. On a
// packed repository the HEAD commit+tree lookup costs more than the index
// parse, and on a reftable repository it re-enters the git CLI (gitrepo routes
// reference reads through a subprocess there), which is ~150x the cost of the
// index check.
func classifyLocalSettings(ctx context.Context, path string) localTrust {
	return classify(ctx, path, false)
}

// classifyLocalSettingsDeep also checks HEAD, catching content that is
// committed but no longer staged. Reserved for the OPF command, where being
// wrong means executing someone else's binary and the extra cost is paid only
// by the few users who set that field locally.
func classifyLocalSettingsDeep(ctx context.Context, path string) localTrust {
	return classify(ctx, path, true)
}

func classify(ctx context.Context, path string, deep bool) localTrust {
	switch versioned, err := localSettingsIsVersioned(ctx, path, deep); {
	case err != nil:
		return localUnverifiable
	case versioned:
		return localTracked
	default:
		return localOwn
	}
}

// probeKey memoizes the shallow and deep answers separately: the deep probe
// subsumes the shallow one, but they are asked by different callers and only
// the rare OPF path pays for HEAD.
type probeKey struct {
	path string
	deep bool
}

// versionedPaths memoizes localSettingsIsVersioned for the process lifetime.
//
// settings.Load has no caching of its own and runs ~5 times per hook, so an
// unmemoized probe multiplies one repository read into five. Whether a path is
// tracked cannot change inside a single short-lived hook process. Only
// successful determinations are cached; an error means "could not verify" and
// may be transient.
//
// Process-scoped, which is right for hooks but stale for a long-lived `entire
// mcp` server: a developer who untracks the file mid-session keeps the old
// verdict until restart. ClearVersionedPathCache exists for tests; see the
// context-scoped precedent in strategy/git_remote_cache.go if this ever needs
// to become request-scoped.
var (
	versionedPathsMu sync.Mutex
	versionedPaths   = map[probeKey]bool{}
)

// ClearVersionedPathCache drops the memoized trackedness verdicts. Tests that
// change a file's tracked state within one process must call it; every other
// process-wide cache in this codebase ships the same seam.
func ClearVersionedPathCache() {
	versionedPathsMu.Lock()
	defer versionedPathsMu.Unlock()
	clear(versionedPaths)
}

// localSettingsIsVersioned reports whether the local settings file is tracked
// in the index, and with deep set, whether it is also present in HEAD.
//
// An error means "could not determine" (unreadable repository, unreadable
// index) and callers must treat it as untrusted rather than as a negative.
func localSettingsIsVersioned(ctx context.Context, path string, deep bool) (bool, error) {
	key := probeKey{path: path, deep: deep}

	versionedPathsMu.Lock()
	cached, ok := versionedPaths[key]
	versionedPathsMu.Unlock()
	if ok {
		return cached, nil
	}

	versioned, err := probeLocalSettingsIsVersioned(ctx, path, deep)
	if err != nil {
		return false, err
	}

	versionedPathsMu.Lock()
	versionedPaths[key] = versioned
	versionedPathsMu.Unlock()
	return versioned, nil
}

// probeLocalSettingsIsVersioned answers through go-git rather than the git CLI.
// Beyond avoiding a subprocess, this removes a dependency on `git` being on
// $PATH for ordinary repositories — the population running GUI git clients,
// whose hooks do not inherit a shell profile, is precisely the one that needs
// an explicit OPF command and would otherwise fail verification and lose it.
// (Reftable repositories are the exception: gitrepo routes reference reads
// through the git CLI, so the deep check still needs the binary there.)
//
// path is always <worktreeRoot>/.entire/settings.local.json, so the worktree
// root is its grandparent and the repo-relative key is the known constant —
// no git call is needed to resolve either. That coupling is load-bearing: if
// paths.AbsPath ever fell back to a bare relative path from a subdirectory,
// the grandparent would name the wrong directory. It holds today because
// readConfined can only have succeeded on the relative form when the working
// directory IS the worktree root.
func probeLocalSettingsIsVersioned(ctx context.Context, path string, deep bool) (bool, error) {
	if err := ctx.Err(); err != nil {
		return false, fmt.Errorf("verify %s: %w", EntireSettingsLocalFile, err)
	}

	repo, err := gitrepo.OpenPath(filepath.Dir(filepath.Dir(path)))
	if err != nil {
		// No repository at all (no .git). A file cannot have arrived by
		// cloning when there is nothing to clone, so this is a definitive
		// "not versioned", not a verification failure. Treating it as a
		// failure would drop the local layer for every non-repo invocation.
		if errors.Is(err, fs.ErrNotExist) {
			return false, nil
		}
		return false, fmt.Errorf("open repository: %w", err)
	}
	defer func() { _ = repo.Close() }()

	// Index. Paths are stored slash-separated, which EntireSettingsLocalFile
	// already is, on every platform.
	idx, err := repo.Storer.Index()
	if err != nil {
		return false, fmt.Errorf("read index: %w", err)
	}
	for _, entry := range idx.Entries {
		if pathsEqualFold(entry.Name, EntireSettingsLocalFile) {
			return true, nil
		}
	}
	if !deep {
		return false, nil
	}

	// HEAD. An unborn HEAD cannot contain the file, so that is a definitive
	// negative rather than a verification failure.
	head, err := repo.Head()
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return false, nil
		}
		return false, fmt.Errorf("resolve HEAD: %w", err)
	}
	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return false, fmt.Errorf("read HEAD commit: %w", err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return false, fmt.Errorf("read HEAD tree: %w", err)
	}
	return treeHasPathFold(tree, strings.Split(EntireSettingsLocalFile, "/"))
}

// pathsEqualFold reports whether two repo-relative git paths can name the same
// working-tree file once the filesystem has had its say.
//
// The comparison must NOT be exact, because git records the committed name
// while readConfined opens the canonical one, and several filesystems map the
// two together:
//
//   - Case. On a case-insensitive volume (the macOS and Windows default) a pull
//     request can commit `.entire/Settings.Local.json`; checkout materializes a
//     file that readConfined opens through the canonical name.
//   - Trailing dots and spaces. Win32 strips them, so a committed
//     `.entire/settings.local.json.` also lands on disk under the canonical
//     name. This is the class core.protectNTFS defends, but that setting only
//     guards .git-family names, not ours.
//
// Either way the file would be read as settings while an exact lookup judged
// it untracked — precisely the bypass this gate exists to prevent, and for the
// trailing-dot case reachable through an ordinary pull request, since it
// defeats the index check rather than only the HEAD one.
//
// Normalizing unconditionally rather than probing the platform is deliberate:
// no variant of this filename is ever legitimate content, so treating one as
// tracked on Linux too costs at most an ignored local layer plus a warning,
// and it keeps the security-relevant path free of a capability check that
// could itself be wrong.
//
// Residual limits worth knowing. This covers Unicode simple case folding and
// the Win32 trailing-character rule, not every equivalence a filesystem might
// apply (NFC/NFD, for instance); the filename is pure ASCII, so those are not
// the realistic vectors. NTFS alternate data streams are a read-side suffix
// rather than a committable name, and 8.3 short names are generated aliases
// for long names rather than the reverse, so neither is a route in.
func pathsEqualFold(a, b string) bool {
	return strings.EqualFold(normalizePathForFilesystemCompare(a), normalizePathForFilesystemCompare(b))
}

// normalizePathForFilesystemCompare drops the trailing dots and spaces Win32
// strips, per path component. A component that is nothing but those characters
// (".", "..") is left alone: emptying it would change the path's meaning.
func normalizePathForFilesystemCompare(path string) string {
	parts := strings.Split(path, "/")
	for i, part := range parts {
		if trimmed := strings.TrimRight(part, ". "); trimmed != "" {
			parts[i] = trimmed
		}
	}
	return strings.Join(parts, "/")
}

// treeHasPathFold reports whether any fold-matching chain of tree entries
// spells parts. object.Tree.FindEntry matches exactly, so it cannot be used.
//
// It must try EVERY fold-matching entry at each level, not just the first.
// Git objects are case-sensitive, so one tree can legitimately hold both
// `.Entire` and `.entire`, and git sorts uppercase first — so a decoy that
// sorts earlier (a blob by that name, or a directory missing the child) would
// otherwise mask the real sibling and produce a false negative. That is the
// "any variant is tracked" semantics the index scan already has; the two sides
// of this predicate must not disagree.
func treeHasPathFold(tree *object.Tree, parts []string) (bool, error) {
	if len(parts) == 0 {
		return false, nil
	}
	part, rest := parts[0], parts[1:]

	for i := range tree.Entries {
		entry := &tree.Entries[i]
		if !pathsEqualFold(entry.Name, part) {
			continue
		}
		if len(rest) == 0 {
			return true, nil
		}
		sub, err := tree.Tree(entry.Name)
		if err != nil {
			if errors.Is(err, object.ErrDirectoryNotFound) {
				continue // a blob where a directory was expected: try siblings
			}
			return false, fmt.Errorf("read %s in HEAD: %w", entry.Name, err)
		}
		found, err := treeHasPathFold(sub, rest)
		if err != nil {
			return false, err
		}
		if found {
			return true, nil
		}
	}
	return false, nil
}

package settings

import (
	"context"
	"encoding/json"
)

// externalAgentsRejectionNotLocal and ...NotVerified explain why an
// external_agents grant was dropped. They mirror the OPF command's reasons
// because the hazard is the same one: a JSON settings diff that grants
// execution does not read as executable to a reviewer.
const (
	externalAgentsRejectionNotLocal   = "it did not come from .entire/settings.local.json"
	externalAgentsRejectionUnverified = "the local settings file could not be verified as untracked"
)

// enforceExternalAgentsTrust drops external_agents unless it came from a local
// file positively verified as this developer's own.
//
// external_agents is not a preference. It turns on the $PATH scan that globs
// for entire-agent-* binaries and runs each one's "info" subcommand, and it
// keeps running them for every hook thereafter. Honoring it from the
// version-controlled .entire/settings.json would let an ordinary pull request
// pair `{"external_agents": true}` with a binary committed next to it (or
// merely present on a shared machine's $PATH) and get it executed on every
// developer who pulls. The reasoning in enforceOPFCommandTrust applies
// unchanged: one line of JSON is a poor place to hide an exec grant, and there
// is no prompt in front of this one at all.
//
// localData is the raw local-file bytes, nil when the file is absent or its
// layer was dropped as tracked. The deep (index AND HEAD) check is used and
// localOwn is required: like the OPF command and unlike the layer as a whole,
// an unverifiable repository fails CLOSED, because being wrong means running
// someone else's binary rather than losing a preference.
//
// Rejection is a downgrade, never an error. Discovery simply does not run, and
// the user's own agents are unaffected — the interactive setup flows call
// DiscoverAndRegisterAlways and reach external plugins regardless, so the
// remedy stays available from the command that needs it.
func enforceExternalAgentsTrust(ctx context.Context, s *EntireSettings, localSettingsPath string, localData []byte) {
	// Only a true value grants anything, so only a true value is gated.
	// Warning about a false one would be noise about a privilege nobody asked
	// for.
	if s == nil || !s.ExternalAgents {
		return
	}

	var reason string
	switch {
	case !localSetsExternalAgents(localData):
		reason = externalAgentsRejectionNotLocal
	case classifyLocalSettingsDeep(ctx, localSettingsPath) != localOwn:
		reason = externalAgentsRejectionUnverified
	default:
		return
	}

	// Recorded rather than logged, for the reasons in enforceOPFCommandTrust:
	// the loader runs while the log level is still being resolved, and a line
	// in .entire/logs is not a signal the user sees.
	s.externalAgentsRejection = reason
	s.ExternalAgents = false
}

// localSetsExternalAgents reports whether the local override file explicitly
// sets external_agents.
//
// Presence of the key is what matters, not the merged value: both files may
// set true, and comparing effective values after the merge would credit the
// project layer for the local file's grant. A malformed local file yields
// false, the safe direction — the merge reports the parse error separately.
func localSetsExternalAgents(data []byte) bool {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return false
	}
	return rawHasKey(raw, "external_agents")
}

