	assert.Contains(t, got, RedactedPlaceholder)
}

func TestJSONLContent_RedactsLeafWithEscapedSolidus(t *testing.T) {
	t.Parallel()

	// \/ decodes to / but Go never re-encodes / as \/, so the search key
	// cannot match the producer's spelling.
