	}
	if err != nil || len(condensed) == 0 {
		if fallback != "" {
			return fallback + "\n"
		}
		return "  (failed to parse transcript)\n"
	}

	input := summarize.Input{Transcript: condensed}
	return summarize.FormatCondensedTranscript(input)
}

