// fetchOwnershipURLs returns the additional repo identities the fetch-side
// ownership check votes with, alongside origin: the caller-supplied read
// candidate, when one resolves. It mirrors the push side's push-URL identity
// set. A candidate that fails to resolve contributes nothing, and the
// ownership check itself already treats a repo with no identity at all as
// inherited.
func fetchOwnershipURLs(ctx context.Context, getRemoteURL func(context.Context, string) (string, error), opt FetchURLOptions) []string {
	lead := opt.LeadReadRemote
	if lead == "" || lead == originRemote {
		return nil
	}
	leadURL, err := getRemoteURL(ctx, lead)
	if err != nil || leadURL == "" {
		return nil
	}
	return []string{leadURL}
}

