			if tt.leadRemote != "" {
				opts = append(opts, FetchURLOptions{LeadReadRemote: tt.leadRemote})
			}
			got, err := FetchURL(context.Background(), opts...)
			if err != nil {
				t.Fatalf("FetchURL() error = %v", err)
			}
			if got != tt.wantURL {
				t.Fatalf("FetchURL() = %q, want %q", got, tt.wantURL)
			}
		})
	}
}

