	_, ok := prefs.ReviewProfiles[name]
	return ok
}

// sortedKeys returns the map's keys in sorted order so rejections are recorded
// deterministically.
func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
