func runEntireInDir(t *testing.T, dir string, args ...string) string {
	t.Helper()
	stdout, stderr, err := runEntire(t, testutil.GitIsolatedEnv(), dir, args...)
	if err != nil {
		t.Fatalf("entire %v failed: %v\n%s%s", args, err, stdout, stderr)

